import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, int stride, int padding);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv2d forward kernel (bf16 in/out, fp32 accumulation).
// Each block computes a tile of PTile = Threads*PVec output pixels (one image)
// for ALL Cout output channels. Weights (Cout x Cin*KH*KW) are staged into
// shared memory once per block; each thread accumulates Cout x PVec partial
// sums in registers and iterates over the K = Cin*KH*KW taps.
template <typename T, int CO>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int KH, int KW,
    int stride, int pad,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int PTile   = Threads * PVec;

  const int tid     = threadIdx.x;
  const int n       = blockIdx.y;
  const int p_block = blockIdx.x * PTile;

  const int P_total = Hout * Wout;
  const int K       = Cin * KH * KW;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)CO * Hout * Wout;

  // Global tensors (per-image views) via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );

  // Stage the (small) filter bank into shared memory as fp32
  extern __shared__ float sW_raw[];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CO>{}, K),
      make_stride(K, Int<1>{})
  );

  for (int idx = tid; idx < CO * K; idx += Threads) {
    int oc = idx / K;
    int t  = idx - oc * K;
    sW(oc, t) = (float)mW(oc, t);
  }
  __syncthreads();

  // Map this thread's pixels (coalesced along width)
  int  oh_arr[PVec];
  int  ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    valid[i] = (p < P_total);
    if (valid[i]) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Register accumulators
  float acc[CO][PVec];
  #pragma unroll
  for (int oc = 0; oc < CO; ++oc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc][i] = 0.0f;
    }
  }

  // Loop over the K = Cin*KH*KW taps
  for (int t = 0; t < K; ++t) {
    int kw = t % KW;
    int r  = t / KW;
    int kh = r % KH;
    int ic = r / KH;

    // Fetch input values for this tap (cached, coalesced across threads)
    float xv[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      xv[i] = 0.0f;
      if (valid[i]) {
        int ih = oh_arr[i] * stride - pad + kh;
        int iw = ow_arr[i] * stride - pad + kw;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          xv[i] = (float)mX(ic, ih, iw);
        }
      }
    }

    // Rank-1 update across all output channels
    #pragma unroll
    for (int oc = 0; oc < CO; ++oc) {
      float wv = sW(oc, t);
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        acc[oc][i] += xv[i] * wv;
      }
    }
  }

  // Epilogue: store results
  #pragma unroll
  for (int oc = 0; oc < CO; ++oc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (valid[i]) {
        mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc][i]);
      }
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(w.scalar_type() == at::kBFloat16, "w must be bfloat16");
  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t Cin  = x_c.size(1);
  const int64_t H    = x_c.size(2);
  const int64_t Win  = x_c.size(3);
  const int64_t Cout = w_c.size(0);
  const int64_t KH   = w_c.size(2);
  const int64_t KW   = w_c.size(3);

  TORCH_CHECK(w_c.size(1) == Cin, "w.size(1) must equal x channels");
  TORCH_CHECK(Cout == 32, "this kernel is specialized for Cout == 32");

  const int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());

  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int PTile   = Threads * PVec;

  const int64_t P_total = Hout * Wout;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)N
  );

  const int K      = (int)(Cin * KH * KW);
  const int smem   = (int)(Cout * K * sizeof(float));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_tiled_kernel<cute::bfloat16_t, 32><<<grid, block, smem, stream>>>(
      reinterpret_cast<const cute::bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const cute::bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<cute::bfloat16_t*>(y.data_ptr<at::BFloat16>()),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)KH, (int)KW,
      stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv_ext = load_inline(
    name="cute_conv2d_bf16_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Parameter storage matches the reference module (state_dict compatible)
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=32,
            kernel_size=3,
            bias=False,
            dtype=torch.bfloat16,
        )
        self._ext = conv_ext

    def forward(self, x):
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.conv1.weight.contiguous(),
            int(self.conv1.stride[0]),
            int(self.conv1.padding[0]),
        )

